# SINO PRO deploy v43 - tuzatilgan 4 fayl + git add/commit/push
# PowerShell 5.1 compatible: no &&, no double quotes, ASCII only.
# Tuzatishlar:
#   1) channel_inbox.py  - AI zaxira: lokal parser topmasa kanal AI ishlaydi
#   2) channel_ocr.py    - tesseract topish/sozlash (rasm va skrinshot oqiladi)
#   3) channel_parse.py  - persian/arab so'zlar, XAUUSDBUY4415, closed above xatosi
#   4) channel_ai.py     - AI lugati (persian/arab) yangilandi
$ErrorActionPreference = 'Stop'
$root = $PSScriptRoot
if (-not $root) { $root = Split-Path -Parent $MyInvocation.MyCommand.Path }
Set-Location $root
Write-Host ''
Write-Host '===== SINO PRO DEPLOY v43 (TUZATISH) =====' -ForegroundColor Cyan
Write-Host ('Papka: ' + $root) -ForegroundColor DarkGray
if (-not (Test-Path (Join-Path $root 'app'))) {
    Write-Host 'XATO: app papkasi yoq - skriptni bot papkasi (repo) ichida saqlang.' -ForegroundColor Red
    Read-Host 'Yopish uchun Enter'
    exit 1
}
if (-not (Test-Path (Join-Path $root '.git'))) {
    Write-Host 'XATO: .git yoq - bu papka git repo emas.' -ForegroundColor Red
    Read-Host 'Yopish uchun Enter'
    exit 1
}

$files = @(
    @{ p = 'app/services/channel_inbox.py'; b = '' },
    @{ p = 'app/services/channel_ai.py'; b = '' },
    @{ p = 'app/services/channel_ocr.py'; b = '' },
    @{ p = 'app/services/channel_parse.py'; b = '' }
)

Write-Host ''
Write-Host ('Fayllar: ' + $files.Count) -ForegroundColor Yellow
foreach ($f in $files) {
    $path = Join-Path $root $f.p
    $dir = Split-Path -Parent $path
    if (-not (Test-Path $dir)) { New-Item -ItemType Directory -Force -Path $dir | Out-Null }
    [System.IO.File]::WriteAllBytes($path, [System.Convert]::FromBase64String($f.b))
    Write-Host ('  tuzatildi: ' + $f.p) -ForegroundColor Green
}

$ok1 = Select-String -Path (Join-Path $root 'app/services/channel_inbox.py') -Pattern 'AI zaxira' -SimpleMatch -Quiet
$ok2 = Select-String -Path (Join-Path $root 'app/services/channel_ocr.py') -Pattern '_TESS_DONE' -SimpleMatch -Quiet
$ok3 = Select-String -Path (Join-Path $root 'app/services/channel_parse.py') -Pattern '_gold_levels' -SimpleMatch -Quiet
if ($ok1 -and $ok2 -and $ok3) {
    Write-Host 'Tekshiruv: tuzatishlar fayllarda bor.' -ForegroundColor Green
} else {
    Write-Host 'OGOHLANTIRISH: marker topilmadi - fayllarni qayta yozib ko''ring.' -ForegroundColor Yellow
}

Write-Host ''
Write-Host '===== GIT PUSH (GitLab: comand-group/sino) =====' -ForegroundColor Cyan

# Push manzili: GitLab. Agar server boshqa domen bolsa - shu qatorni ozgartiring.
$gl_url = 'https://gitlab.com/comand-group/sino.git'
$cur = (git config --get remote.origin.url 2>$null)
if (-not $cur) {
    Write-Host 'origin yoq - GitLab qoshilmoqda...' -ForegroundColor Yellow
    git remote add origin $gl_url
    $cur = (git config --get remote.origin.url 2>$null)
}
if ($cur -notlike '*comand-group/sino*') {
    Write-Host ('origin edi: ' + $cur) -ForegroundColor Yellow
    git remote set-url origin $gl_url
    $cur = (git config --get remote.origin.url 2>$null)
    Write-Host ('origin endi: ' + $gl_url) -ForegroundColor Green
    Write-Host 'Diqqat: force push GitLab dagi shu branchni almashtiradi.' -ForegroundColor Yellow
}
Write-Host ('origin: ' + $cur) -ForegroundColor DarkGray

git add -A
git reset -- .env 2>$null
git status --short
git commit -m 'SINO v43: kanal AI zaxira + tesseract OCR + parser tuzatishlar'
$br = (git rev-parse --abbrev-ref HEAD)
Write-Host ('Branch: ' + $br) -ForegroundColor DarkGray
git push origin $br --force
if ($LASTEXITCODE -ne 0) {
    Write-Host 'Force push rad etildi - oddiy push sinaladi...' -ForegroundColor Yellow
    git push origin $br
}
if ($br -ne 'main') { git push origin ($br + ':main') --force }
if ($br -ne 'master') { git push origin ($br + ':master') --force }

Write-Host ''
Write-Host 'TAYYOR. Endi Render panelida Manual Deploy ni bosing.' -ForegroundColor Green
Write-Host 'Diqqat: v42 skriptini qayta ishga tushirmang - u eski fayllarni qaytaradi.' -ForegroundColor Yellow
$t = Get-Command tesseract -ErrorAction SilentlyContinue
if (-not $t) {
    Write-Host 'ESLATMA: tesseract topilmadi (faqat lokal Windows uchun kerak).' -ForegroundColor Yellow
    Write-Host '  winget install -e --id UB-Mannheim.TesseractOCR' -ForegroundColor Yellow
}
Write-Host ('Push manzili: ' + (git config --get remote.origin.url)) -ForegroundColor DarkGray
Write-Host 'GitLab da Commits ni ochib tekshiring, keyin Render - Manual Deploy.' -ForegroundColor DarkGray
Write-Host 'AI LLM kerak bolsa .env ichiga: AI_API_KEY=gsk_... (ixtiyoriy).' -ForegroundColor DarkGray
Read-Host 'Yopish uchun Enter'
